/**
 * tests/netscape.test.mjs — CONTRACT §4: Netscape cookie text format.
 *
 * All cookie data here is synthetic (fake names/values). No real account material.
 *
 * Run: node --test browser-extension/tests
 */

import assert from "node:assert/strict";
import { describe, it } from "node:test";

import {
  countCookieRecords,
  isCookiesValid,
  serializeNetscapeCookies,
} from "../utils.mjs";

const HEADER = [
  "# Netscape HTTP Cookie File",
  "# This file is generated by VRCVideoCacher.  Do not edit.",
  "",
].join("\n");

/** Synthetic chrome.cookies.Cookie-shaped objects. */
const sampleCookies = [
  {
    domain: "youtube.com",
    path: "/",
    secure: true,
    expirationDate: 1790000000.987,
    name: "LOGIN_INFO",
    value: "FAKE_LOGIN_VALUE",
  },
  {
    domain: ".youtube.com",
    path: "/watch",
    secure: false,
    expirationDate: 1800000000,
    name: "PREF",
    value: "FAKE_PREF_VALUE",
  },
  {
    domain: ".youtube.com",
    path: "/",
    secure: true,
    expirationDate: 1900000000,
    name: "ST-abc123",
    value: "FAKE_SESSION_TOKEN",
  },
];

function recordLines(text) {
  return text
    .split("\n")
    .filter((line) => line.length > 0 && !line.startsWith("#"));
}

describe("serializeNetscapeCookies", () => {
  const text = serializeNetscapeCookies(sampleCookies);
  const lines = recordLines(text);

  it("writes the exact upstream header", () => {
    assert.ok(text.startsWith(HEADER), "header must match CONTRACT §4 byte for byte");
  });

  it("ends with exactly one trailing newline", () => {
    assert.ok(text.endsWith("\n"));
    assert.ok(!text.endsWith("\n\n"), "no double trailing newline");
  });

  it("drops Firefox ST- cookies (CONTRACT §4)", () => {
    assert.equal(lines.length, 2);
    assert.ok(!text.includes("ST-abc123"));
    assert.ok(!text.includes("FAKE_SESSION_TOKEN"));
  });

  it("emits exactly 7 tab separated fields per record", () => {
    for (const line of lines) {
      assert.equal(line.split("\t").length, 7, `bad field count: ${line}`);
    }
  });

  it("forces a leading dot on the domain", () => {
    assert.equal(lines[0].split("\t")[0], ".youtube.com");
    assert.equal(lines[1].split("\t")[0], ".youtube.com");
  });

  it("does not double the dot when the domain already has one", () => {
    for (const line of lines) {
      assert.ok(!line.startsWith(".."), "domain must not become '..youtube.com'");
    }
  });

  it("keeps the contract field order and literal values", () => {
    const f = lines[0].split("\t");
    assert.deepEqual(f, [
      ".youtube.com", // domain
      "TRUE", // includeSubdomains
      "/", // path
      "TRUE", // secure
      "1790000000", // Math.floor(expirationDate)
      "LOGIN_INFO",
      "FAKE_LOGIN_VALUE",
    ]);
  });

  it("maps secure false to FALSE", () => {
    const f = lines[1].split("\t");
    assert.equal(f[2], "/watch");
    assert.equal(f[3], "FALSE");
    assert.equal(f[5], "PREF");
  });

  it("floors fractional expiry and uses 0 for session cookies", () => {
    assert.equal(lines[0].split("\t")[4], "1790000000");
    const session = serializeNetscapeCookies([
      { domain: ".youtube.com", path: "/", secure: true, name: "PREF", value: "x" },
    ]);
    assert.equal(recordLines(session)[0].split("\t")[4], "0");
  });
});

describe("serializeNetscapeCookies — invalid input", () => {
  it("tolerates null / undefined / non-array without throwing", () => {
    for (const input of [null, undefined, 42, "not-an-array", {}]) {
      const text = serializeNetscapeCookies(input);
      assert.equal(typeof text, "string");
      assert.equal(recordLines(text).length, 0);
      assert.ok(text.startsWith(HEADER));
    }
  });

  it("skips entries without a name or domain", () => {
    const text = serializeNetscapeCookies([
      null,
      undefined,
      { domain: ".youtube.com", name: "", value: "v" },
      { domain: "", name: "PREF", value: "v" },
      { name: "PREF", value: "v" },
      { domain: ".youtube.com", path: "/", secure: true, name: "PREF", value: "ok" },
    ]);
    const lines = recordLines(text);
    assert.equal(lines.length, 1);
    assert.equal(lines[0].split("\t")[5], "PREF");
  });

  it("defaults a missing path to '/' and a missing value to ''", () => {
    const text = serializeNetscapeCookies([
      { domain: ".youtube.com", secure: true, name: "PREF" },
    ]);
    const f = recordLines(text)[0].split("\t");
    assert.equal(f.length, 7);
    assert.equal(f[2], "/");
    assert.equal(f[6], "");
  });
});

describe("isCookiesValid (Program.IsCookiesValid parity)", () => {
  it("accepts text containing youtube.com and LOGIN_INFO", () => {
    assert.equal(isCookiesValid(serializeNetscapeCookies(sampleCookies)), true);
  });

  it("rejects text missing LOGIN_INFO", () => {
    assert.equal(
      isCookiesValid(serializeNetscapeCookies([sampleCookies[1]])),
      false,
    );
  });

  it("rejects non-strings and empty strings", () => {
    for (const input of [null, undefined, "", 0, {}]) {
      assert.equal(isCookiesValid(input), false);
    }
  });
});

describe("countCookieRecords", () => {
  it("counts only 7-field non-comment lines", () => {
    const text = serializeNetscapeCookies(sampleCookies);
    assert.equal(countCookieRecords(text), 2);
  });

  it("returns 0 for empty/garbage input", () => {
    assert.equal(countCookieRecords(""), 0);
    assert.equal(countCookieRecords(null), 0);
    assert.equal(countCookieRecords(HEADER), 0);
  });
});
